<?php declare(strict_types=1); use N3\Module\Blog\BlogListing; use N3\Module\Blog\BlogPost; $listing = ($viewData['listing'] ?? null) instanceof BlogListing ? $viewData['listing'] : null; ?>
<header class="site-header"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">N3</span><span>N3</span></a><nav aria-label="Blog"><a href="/">Home</a><a href="/blog" aria-current="page">Blog</a></nav></header>
<main class="blog-page" id="main-content">
    <header class="blog-heading"><p class="eyebrow">Latest writing</p><h1>Blog</h1><p>Published updates from this N3 site.</p></header>
    <?php if ($listing === null || $listing->posts === []): ?><section class="empty-state" aria-labelledby="empty-blog"><h2 id="empty-blog">No posts published yet</h2><p>Check back later for updates.</p></section>
    <?php else: ?><div class="blog-list"><?php foreach ($listing->posts as $post): if (!$post instanceof BlogPost) { continue; } ?><article class="blog-card"><p class="blog-date"><time datetime="<?= $escape(str_replace(' ', 'T', (string) $post->publishedAt) . 'Z') ?>"><?= $escape(substr((string) $post->publishedAt, 0, 10)) ?></time></p><h2><a href="/blog/<?= $escape($post->slug) ?>"><?= $escape($post->title) ?></a></h2><?php if ($post->excerpt !== ''): ?><p><?= $escape($post->excerpt) ?></p><?php endif; ?><a class="blog-read" href="/blog/<?= $escape($post->slug) ?>">Read post<span class="visually-hidden">: <?= $escape($post->title) ?></span></a></article><?php endforeach; ?></div><?php endif; ?>
    <?php if ($listing !== null && $listing->totalPages > 1): ?><nav class="pagination" aria-label="Blog pages"><?php if ($listing->page > 1): ?><a rel="prev" href="<?= $listing->page === 2 ? '/blog' : '/blog?page=' . $escape($listing->page - 1) ?>">Previous</a><?php endif; ?><span aria-live="polite">Page <?= $escape($listing->page) ?> of <?= $escape($listing->totalPages) ?></span><?php if ($listing->page < $listing->totalPages): ?><a rel="next" href="/blog?page=<?= $escape($listing->page + 1) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
</main>
